```javascript
// 1. 弹出确认窗口，等待用户点击
eda.sys_MessageBox.showConfirmationMessage(
  '即将删除选中的 3 个图元，是否继续？',
  '删除确认',   // 窗口标题
  '删除',       // 主按钮（确认）
  '取消',       // 次按钮（取消）
  (mainButtonClicked) => {
    if (mainButtonClicked) {
      console.log('用户点击了主按钮（删除）');
    } else {
      console.log('用户点击了次按钮（取消）');
    }
  }
);

// 2. 窗口已弹出，本方法无返回值；回调需用户点击按钮后才会触发
console.log('已弹出确认窗口');
```
